public class Solution {
  /**
   * 显式栈的 RPN 求值：long[] 当栈，sp 是栈大小（半开区间 [0, sp)）。
   * 数值语义钉死三件事：
   *  1) 加减乘走 Math.*Exact —— 溢出抛 ArithmeticException，绝不回绕；
   *  2) 除法用 Math.floorDiv（向下取整），与离线口径一致；
   *  3) JDK17 没有 floorDivExact，所以 Long.MIN_VALUE / -1 要显式判溢出。
   */
  public static long evalRpn(String rpn, int[] vars) {
    if (rpn == null || rpn.trim().isEmpty()) return 0L;
    String[] tokens = rpn.trim().split(" +");
    long[] stack = new long[tokens.length];
    int sp = 0;
    for (String token : tokens) {
      if (token.equals("+") || token.equals("-") || token.equals("*") || token.equals("/")) {
        if (sp < 2) throw new IllegalArgumentException("rpn stack underflow");
        long b = stack[--sp];
        long a = stack[--sp];
        long value;
        if (token.equals("+")) {
          value = Math.addExact(a, b);
        } else if (token.equals("-")) {
          value = Math.subtractExact(a, b);
        } else if (token.equals("*")) {
          value = Math.multiplyExact(a, b);
        } else {
          if (a == Long.MIN_VALUE && b == -1L) throw new ArithmeticException("long overflow");
          value = Math.floorDiv(a, b);
        }
        stack[sp++] = value;
      } else if (token.charAt(0) == '$') {
        int pos;
        try {
          pos = Integer.parseInt(token.substring(1));
        } catch (NumberFormatException bad) {
          throw new IllegalArgumentException("bad variable token: " + token);
        }
        if (pos < 0 || pos >= vars.length) throw new IllegalArgumentException("unknown variable: " + token);
        stack[sp++] = vars[pos];
      } else {
        try {
          stack[sp++] = Long.parseLong(token);
        } catch (NumberFormatException bad) {
          throw new IllegalArgumentException("bad literal: " + token);
        }
      }
    }
    if (sp != 1) throw new IllegalArgumentException("expression must leave exactly one value");
    return stack[0];
  }
}

