public class Solution {
  // 朴素：ArrayDeque<Integer> 当栈 + Java 内建 / 截断除法。
  // 两处必错：(1) 与离线口径不一致（-7/2 得 -3 而不是 -4）；
  //           (2) 中间量按 int 计算 —— 大数相加回绕成负数，静默写进特征表。
  public static long evalRpn(String rpn, int[] vars) {
    if (rpn == null || rpn.trim().isEmpty()) return 0L;
    String[] tokens = rpn.trim().split(" +");
    java.util.ArrayDeque<Integer> stack = new java.util.ArrayDeque<>();
    for (String token : tokens) {
      switch (token) {
        case "+": {
          int b = stack.pop();
          int a = stack.pop();
          stack.push(a + b);
          break;
        }
        case "-": {
          int b = stack.pop();
          int a = stack.pop();
          stack.push(a - b);
          break;
        }
        case "*": {
          int b = stack.pop();
          int a = stack.pop();
          stack.push(a * b);
          break;
        }
        case "/": {
          int b = stack.pop();
          int a = stack.pop();
          stack.push(a / b);
          break;
        }
        default:
          if (token.charAt(0) == '$') {
            stack.push(vars[Integer.parseInt(token.substring(1))]);
          } else {
            stack.push((int) Long.parseLong(token));
          }
      }
    }
    return stack.pop();
  }
}
